t.script:
(function(){
    function ajaxUpdate(line_id, delta, button){
        var payload = {line_id: line_id, quantity: delta};
        fetch('/custom_checkout/update_line_qty', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
            },
            body: JSON.stringify(payload),
            credentials: 'same-origin'
        })
        .then(function(resp){
            return resp.json();
        })
        .then(function(data){
            data = data.result
            if(!data || !data.success){
                console.warn('update failed', data);
                return;
            }
            // find input by data-line-id (use custom class to avoid Odoo default handlers)
            var inputs = document.querySelectorAll('input.custom_js_quantity[data-line-id="'+line_id+'"]');
            if(inputs && inputs.length){
                var input = inputs[0];
                if(data.new_qty <= 0){
                    // remove DOM element for the line
                    var lineEl = input.closest('.o_cart_product');
                    if(lineEl) lineEl.remove();
                } else {
                    input.value = data.new_qty;
                }
            }
            res = data;
            // update all matching cart quantity badge(s)
            var badgeSelectors = ['.my_cart_quantity', '[data-cart-quantity]'];
            badgeSelectors.forEach(function(sel){
                var els = document.querySelectorAll(sel);
                els.forEach(function(el){
                    el.textContent = res.cart_quantity || 0;
                    if(el.classList && el.classList.contains('d-none')){
                        el.classList.toggle('d-none', (res.cart_quantity || 0) === 0);
                    }
                });
            });
            // keep website_sale session storage in sync so other website JS sees the change
            try{
                if(window.sessionStorage){
                    sessionStorage.setItem('website_sale_cart_quantity', String(res.cart_quantity || 0));
                }
            }catch(e){/* ignore */}
            // if cart is now empty, replace the cart+form row with the empty-cart message
            try{
                if((res.cart_quantity || 0) === 0){
                    var cartBlock = document.querySelector('#cart_products');
                    if(cartBlock){
                        var row = cartBlock.closest('.row');
                        if(row){
                            row.outerHTML = '<p class="text-center text-muted">Your cart is empty.</p>';
                        }
                    }
                }
            }catch(e){/* ignore */}
            // dispatch a custom event so other scripts (or themes) can react
            try{
                var evt = new CustomEvent('custom_cart:updated', {detail: {cart_quantity: res.cart_quantity || 0}});
                document.dispatchEvent(evt);
                if(window.jQuery){
                    jQuery(document).trigger('custom_cart:updated', [res.cart_quantity || 0]);
                }
            }catch(e){/* ignore */}
        }).catch(function(err){
            console.error('AJAX error', err);
        });
    }

    document.addEventListener('click', function(ev){
        var el = ev.target;
        // handle clicks on the +/- buttons inside .custom_js_add_cart (custom controls)
        var btn = el.closest && el.closest('.custom_js_add_cart');
        if(btn){
                    ev.preventDefault();
                    // prevent other listeners (website default handlers) from running and redirecting
                    if (ev.stopImmediatePropagation) ev.stopImmediatePropagation();
            // prefer dataset where possible
            var lineIdRaw = (btn.dataset && btn.dataset.lineId) || btn.getAttribute('data-line-id') || btn.getAttribute('t-att-data-line-id');
            var deltaRaw = (btn.dataset && btn.dataset.quantity) || btn.getAttribute('data-quantity') || btn.getAttribute('t-att-data-quantity') || '0';
            var lineId = parseInt(lineIdRaw, 10);
            var delta = parseInt(deltaRaw, 10) || 0;
            if(isNaN(lineId)){
                console.error('invalid line id on button', lineIdRaw, btn);
                return;
            }
            var payload = {line_id: lineId, quantity: delta};
            console.debug('update_line_qty payload', payload);
            ajaxUpdate(lineId, delta, btn);
        }
        // handle clicks on delete links/buttons (.custom_js_delete_product)
        var del = el.closest && el.closest('.custom_js_delete_product');
        if(del){
            ev.preventDefault();
            if (ev.stopImmediatePropagation) ev.stopImmediatePropagation();
            var lineIdRaw = (del.dataset && del.dataset.lineId) || del.getAttribute('data-line-id') || del.getAttribute('t-att-data-line-id');
            var lineId = parseInt(lineIdRaw, 10);
            if(isNaN(lineId)){
                console.error('invalid line id on delete', lineIdRaw, del);
                return;
            }
            // send set_qty=0 to remove the line server-side
            fetch('/custom_checkout/update_line_qty', {
                method: 'POST',
                headers: {'Content-Type': 'application/json','Accept': 'application/json'},
                body: JSON.stringify({line_id: lineId, set_qty: 0}),
                credentials: 'same-origin'
            }).then(function(r){ return r.json(); }).then(function(res){
                var data = res.result || res;
                if(!data || !data.success){
                    console.warn('remove line failed', data);
                    return;
                }
                // remove DOM line if exists
                try{
                    var inputs = document.querySelectorAll('input.custom_js_quantity[data-line-id="'+lineId+'"]');
                    if(inputs && inputs.length){
                        var input = inputs[0];
                        var lineEl = input.closest('.o_cart_product');
                        if(lineEl) lineEl.remove();
                    }
                    // update badge(s)
                    var badgeSelectors = ['.my_cart_quantity', '[data-cart-quantity]'];
                    badgeSelectors.forEach(function(sel){
                        var els = document.querySelectorAll(sel);
                        els.forEach(function(el){
                            el.textContent = data.cart_quantity || 0;
                            if(el.classList && el.classList.contains('d-none')){
                                el.classList.toggle('d-none', (data.cart_quantity || 0) === 0);
                            }
                        });
                    });
                    // if cart empty after removal, replace the cart+form area with empty message
                    try{
                        if((data.cart_quantity || 0) === 0){
                            var cartBlock = document.querySelector('#cart_products');
                            if(cartBlock){
                                var row = cartBlock.closest('.row');
                                if(row){
                                    row.outerHTML = '<p class="text-center text-muted">Your cart is empty.</p>';
                                }
                            }
                        }
                    }catch(e){/* ignore */}
                    try{ if(window.sessionStorage){ sessionStorage.setItem('website_sale_cart_quantity', String(data.cart_quantity || 0)); } }catch(e){}
                    try{ var evt = new CustomEvent('custom_cart:updated', {detail: {cart_quantity: data.cart_quantity || 0}}); document.dispatchEvent(evt); if(window.jQuery){ jQuery(document).trigger('custom_cart:updated', [data.cart_quantity || 0]); } }catch(e){}
                }catch(e){ console.error('remove handler error', e); }
            }).catch(function(e){ console.error('remove ajax error', e); });
        }
    }, true);
    // Listen for direct quantity edits and send absolute updates (debounced)
    var qtyTimers = {};
    document.addEventListener('input', function(ev){
        var input = ev.target;
        // listen only to changes on our custom inputs to avoid Odoo default handlers
        if(!input || !input.classList || !input.classList.contains('custom_js_quantity')) return;
        ev.stopPropagation();
        ev.stopImmediatePropagation();
        ev.preventDefault();
        var lineIdRaw = input.getAttribute('data-line-id') || input.getAttribute('t-att-data-line-id');
        var lineId = parseInt(lineIdRaw, 10);
        if(isNaN(lineId)) return;
        var rawVal = input.value;
        if(typeof rawVal === 'string') rawVal = rawVal.trim();
        // If empty string, do not update the cart (user still typing)
        if(rawVal === '' || rawVal === null || typeof rawVal === 'undefined'){
            return;
        }
        var val = parseInt(rawVal, 10);
        if(isNaN(val)){
            console.error('invalid qty input', rawVal);
            return;
        }
        // debounce
        if(qtyTimers[lineId]) clearTimeout(qtyTimers[lineId]);
        qtyTimers[lineId] = setTimeout(function(){
            console.debug('update_line_qty set payload', {line_id: lineId, set_qty: val});
            fetch('/custom_checkout/update_line_qty', {
                method: 'POST',
                headers: {'Content-Type': 'application/json','Accept': 'application/json'},
                body: JSON.stringify({line_id: lineId, set_qty: val}),
                credentials: 'same-origin'
            }).then(function(r){return r.json();}).then(function(res){
                var data = res.result || res;
                if(!data || !data.success){
                    console.warn('set_qty update failed', data);
                    return;
                }
                if(data.new_qty <= 0){
                    var lineEl = input.closest('.o_cart_product'); if(lineEl) lineEl.remove();
                } else {
                    input.value = data.new_qty;
                }
                // update cart badge(s) to keep header in sync
                try{
                    var badgeSelectors = ['.my_cart_quantity', '[data-cart-quantity]'];
                    badgeSelectors.forEach(function(sel){
                        var el = document.querySelector(sel);
                        if(!el) return;
                        el.textContent = data.cart_quantity || 0;
                        if(el.classList && el.classList.contains('d-none')){
                            el.classList.toggle('d-none', (data.cart_quantity || 0) === 0);
                        }
                    });
                    if(window.sessionStorage){
                        sessionStorage.setItem('website_sale_cart_quantity', String(data.cart_quantity || 0));
                    }
                    // if cart empty after set_qty, replace the cart+form area with empty message
                    try{
                        if((data.cart_quantity || 0) === 0){
                            var cartBlock2 = document.querySelector('#cart_products');
                            if(cartBlock2){
                                var row2 = cartBlock2.closest('.row');
                                if(row2){
                                    row2.outerHTML = '<p class="text-center text-muted">Your cart is empty.</p>';
                                }
                            }
                        }
                    }catch(e){/* ignore */}
                }catch(err){
                    console.error('badge update error', err);
                }
            }).catch(function(e){console.error(e);});
        }, 700);
    }, true);
})();
